arguments.keystrokes:
cat << 'EOF' > /tmp/find_mains.py
import zipfile, glob
for j in glob.glob('/opt/tools/lib/igv/*.jar'):
    try:
        z = zipfile.ZipFile(j)
        for n in z.namelist():
            if n.endswith('.class'):
                data = z.read(n)
                if b'main' in data and b'([Ljava/lang/String;)V' in data:
                    print(f"{j.split('/')[-1]}: {n}")
    except Exception as e:
        pass
EOF
python3 /tmp/find_mains.py

